#include "next/integration/session.hpp"
#include "engine/catalytic.hpp"
#include <iostream>
using namespace r62;using namespace core;using namespace studio::catalytic;
int main(){integration::Session s;std::vector<ObjectId> nodes;for(int i=0;i<4;++i){ObjectId id;s.doc.addAtom(Vec2(i*40,20),46,&id);s.doc.setAtomLabel(id,"Pd");auto sem=s.doc.atoms().alive(id)->semantics;sem.showLabel=true;sem.implicitHydrogens=0;s.doc.setAtomSemantics(id,sem);nodes.push_back(id);}std::vector<ObjectRef> links;auto e=arrange(s.doc,nodes,Vec2(200,200),120,100,true,&links);if(!e.ok()){std::cerr<<e.message;return 1;}for(auto ref:links){arrows::ArrowParams p;bool ok=false;arrows::readArrow(s.doc,ref.id,&p,&ok);if(!ok||!p.electronSource.valid()||p.mechanism){std::cerr<<"binding";return 2;}}ObjectId reagent,branch;s.doc.addAtom(Vec2(400,200),8,&reagent);e=link(s.doc,ObjectRef(ObjectKind::Atom,reagent),links[0],"in",.3,&branch);if(!e.ok())return 3;std::vector<ObjectRef> reused;e=arrange(s.doc,nodes,Vec2(200,200),130,120,false,&reused);if(!e.ok()||reused!=links)return 4;auto before=s.doc.digest();auto id=nodes[0];e=s.submit(Command("move",kInvalidateGeometry,[id](CommandContext& c){auto e=integration::translateDocumentObjects(c.document,component(c.document,id),Vec2(10,10));return e.ok()?CommandResult::success():CommandResult::fail(e.code,e.message);}),"move");if(!e.ok()){std::cerr<<e.message;return 5;}if(!s.undo().ok()||s.doc.digest()!=before)return 6;std::cout<<"cycle, bindings, reverse reuse, linked motion undo passed\n";}
